15	/**
16	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
17	 * so tests can assert side-effects by reading that file — the second test-assertion channel
18	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
19	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
20	 *
21	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
22	 * SYNC) so a test reads the record immediately.
23	 */
24	@Service
25	public class Audit {
26	
27	    private final Path file;
28	
29	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
30	        this.file = Path.of(path);
31	    }
32	
33	    /** Append one audit record. Tests assert the exact line(s) in the file. */
34	    public synchronized void record(String entry) {
35	        try {
36	            Path parent = file.toAbsolutePath().getParent();
37	            if (parent != null) {
38	                Files.createDirectories(parent);
39	            }
40	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
41	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
42	        } catch (IOException e) {
43	            throw new UncheckedIOException(e);
44	        }
45	    }
46	
47	    /**
48	     * Append one audit record once the current transaction commits, so a change that is refused or
49	     * rolled back writes nothing. Without a transaction the record is appended at once.
50	     */
51	    public void recordOnCommit(String entry) {
52	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
53	            record(entry);
54	            return;
55	        }
56	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
57	            @Override
58	            public void afterCommit() {
59	                record(entry);
60	            }
61	        });
62	    }
63	
64	    /** Truncate the audit file. */
65	    public synchronized void clear() {
66	        try {
67	            Files.deleteIfExists(file);
68	        } catch (IOException e) {
69	            throw new UncheckedIOException(e);
70	        }
71	    }
