177	    /** Add a claim for a person; without a date it is dated the sheet's today. */
178	    @Transactional
179	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
180	        Person person = people.findByIdAndSheetId(personId, sheetId)
181	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
182	        Claim saved = claims.saveAndFlush(new Claim(sheetId, personId, amount, dateOrToday(sheetId, date), noteOf(note)));
183	        audit(sheetId, user, "CLAIM_ADDED", person, saved);
184	        return saved;
185	    }
