188	    @Transactional
189	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
190	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
191	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
192	        claim.setAmount(amount);
193	        claim.setDate(dateOrToday(sheetId, date));
194	        claim.setNote(noteOf(note));
195	        Claim saved = claims.saveAndFlush(claim);
196	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
197	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
198	        audit(sheetId, user, "CLAIM_EDITED", person, saved);
199	        return saved;
200	    }
