202	    /** Move a claim to its next status; a change its current status does not allow is refused. */
203	    @Transactional
204	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
205	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
206	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
207	        if (!claim.getStatus().canBecome(next)) {
208	            throw new ResponseStatusException(HttpStatus.CONFLICT,
209	                    "A " + claim.getStatus() + " claim cannot become " + next);
210	        }
211	        claim.setStatus(next);
212	        Claim saved = claims.saveAndFlush(claim);
213	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
214	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
215	        String event = switch (next) {
216	            case OPEN -> "CLAIM_OPENED";
217	            case SETTLED -> "CLAIM_SETTLED";
