424	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID. */
425	public enum ClaimStatus {
426	    DRAFT, OPEN, SETTLED, VOID;
427	
428	    /** Whether a claim in this status may move to {@code next}. */
429	    public boolean canBecome(ClaimStatus next) {
430	        return switch (next) {
431	            case OPEN -> this == DRAFT;
432	            case SETTLED -> this == OPEN;
433	            case VOID -> this == DRAFT || this == OPEN;
434	            case DRAFT -> false;
435	        };
436	    }
