554	
555	    private final PersonRepository people;
556	    private final SheetService sheets;
557	    private final Audit audit;
558	
559	    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
560	        this.people = people;
561	        this.sheets = sheets;
562	        this.audit = audit;
563	    }
564	
565	    /** The sheet's people, in the order they were added. */
566	    @Transactional(readOnly = true)
567	    public List<Person> list(String sheetId) {
568	        return people.findBySheetIdOrderByIdAsc(sheetId);
569	    }
570	
571	    /** Add a person (the sheet is started when it was never loaded before). */
572	    @Transactional
573	    public Person add(String sheetId, String user, String name, Grade grade) {
574	        sheets.load(sheetId, user);
575	        String trimmed = name.trim();
576	        requireUnusedName(sheetId, null, trimmed);
577	        Person saved;
578	        try {
579	            saved = people.saveAndFlush(new Person(sheetId, trimmed, grade));
580	        } catch (DataIntegrityViolationException e) {
581	            throw nameInUse();
582	        }
583	        audit(sheetId, user, "PERSON_ADDED", saved);
584	        return saved;
585	    }
586	
587	    /** Change a person's name and grade. */
588	    @Transactional
589	    public Person edit(String sheetId, String user, long personId, String name, Grade grade) {
590	        Person person = people.findByIdAndSheetId(personId, sheetId)
591	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
592	        String trimmed = name.trim();
593	        requireUnusedName(sheetId, personId, trimmed);
594	        person.setName(trimmed);
595	        person.setGrade(grade);
596	        Person saved;
597	        try {
598	            saved = people.saveAndFlush(person);
599	        } catch (DataIntegrityViolationException e) {
600	            throw nameInUse();
601	        }
602	        audit(sheetId, user, "PERSON_EDITED", saved);
603	        return saved;
604	    }
605	
606	    private void audit(String sheetId, String user, String event, Person person) {
607	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
608	                + " name=" + person.getName() + " grade=" + person.getGrade());
609	    }
610	
611	    /** Refuse a name another person on the sheet already has, ignoring case. */
612	    private void requireUnusedName(String sheetId, Long personId, String name) {
613	        String key = name.toLowerCase(Locale.ROOT);
614	        boolean used = people.findBySheetIdOrderByIdAsc(sheetId).stream()
615	                .anyMatch(p -> !p.getId().equals(personId) && p.getName().toLowerCase(Locale.ROOT).equals(key));
616	        if (used) throw nameInUse();
617	    }
